def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    blocks=[]
    for i in range(H-2):
        for j in range(W-2):
            c=g[i][j]
            if c!=0 and all(g[i+a][j+b]==c for a in range(3) for b in range(3)):
                blocks.append((i+1,j+1,c))
    rows={}; cols={}
    for ci,cj,c in blocks:
        rows[ci]=c; cols[cj]=c
        for j in range(W): g[ci][j]=c
        for i in range(H): g[i][cj]=c
    for r in rows:
        for c in cols:
            if rows[r]!=cols[c]:
                g[r][c]=0
    return g
